 return `<div class="statement-chart cash-waterfall"><header><p class="eyebrow">CASH FLOW WATERFALL</p><h3>现金变化瀑布图</h3><p>${esc(period)} · ${esc(unit)} · ${hasBridge?`${esc(previous.period)} 期末现金作为本期期初`:'三类活动形成的现金净变化'}</p></header><svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet"><line x1="20" y1="${base}" x2="880" y2="${base}" class="waterfall-axis"/>${bars}</svg><div class="cash-summary"><span>三类活动净变化 <b>${net>=0?'+':''}${fmt(net)}</b></span><span>期末现金余额 <b>${fmt(ending)}</b></span></div></div>`
