 const circles=items.map((x,i)=>{const len=Number(x.value)/total*circ,off=-used;used+=len;return`<circle cx="110" cy="110" r="${r}" fill="none" stroke="${colors[i%colors.length]}" stroke-width="32" stroke-dasharray="${len} ${circ-len}" stroke-dashoffset="${off}"/>`}).join(''),history=s.history||[];
