function chartSeries(ids,metric,frequency,mode){return ids.map(cid=>{let vals=state.financials.filter(r=>r.companyId===cid&&r.metric===metric&&r.frequency===frequency).sort((a,b)=>a.period.localeCompare(b.period)).map(r=>({period:r.period,value:Number(r.value),currency:r.currency,unit:r.unit||''}));if(mode==='growth')vals=vals.map((x,i)=>({...x,value:i&&vals[i-1].value!==0?(x.value/vals[i-1].value-1)*100:null,unit:'%'})).filter(x=>x.value!==null);if(mode==='index'){const base=vals.find(x=>x.value!==0);vals=base?vals.map(x=>({...x,value:x.value/base.value*100,unit:'指数',currency:''})):[]}return{company:company(cid),values:vals}})}
function drawChart(root,ids,metric,frequency,mode){
 const series=chartSeries(ids,metric,frequency,mode),all=series.flatMap(s=>s.values),periods=[...new Set(all.map(x=>x.period))].sort(),colors=['#5b5ce2','#7758d8','#3979d7','#9b59d0','#4f46c8'];
 if(!all.length){root.innerHTML=`<div class="chart-head"><div><p class="eyebrow">DATABASE CHART</p><h3>${esc(BY_EN[metric]?.zh)} / ${esc(metric)}</h3></div></div><div class="empty"><div><b>暂无可绘制数据 / No chart data</b>缺失值保持 N/A，不填充为 0。</div></div>`;return}
 const W=900,H=300,p={l:92,r:45,t:38,b:42},vs=all.map(x=>x.value),rawLo=Math.min(...vs),rawHi=Math.max(...vs),span=rawHi===rawLo?Math.max(Math.abs(rawHi)*.2,1):rawHi-rawLo,roughLow=rawLo-span*.14,roughHi=rawHi+span*.14,roundBase=Math.pow(10,Math.max(-4,Math.floor(Math.log10(Math.max(span,1e-9)))-1));let low=Math.round(roughLow/roundBase)*roundBase,hi=Math.round(roughHi/roundBase)*roundBase;if(hi<=low){low=roughLow;hi=roughHi}const range=hi-low;
 const x=k=>p.l+periods.indexOf(k)/Math.max(1,periods.length-1)*(W-p.l-p.r),y=v=>p.t+(hi-v)/range*(H-p.t-p.b),ticks=[0,.25,.5,.75,1].map(q=>Math.round((hi-q*range)/roundBase)*roundBase);
 const num=v=>Number(v).toLocaleString('zh-CN',{maximumFractionDigits:Math.abs(range)<10?2:Math.abs(range)<100?1:0});
 const unit=v=>{if(mode==='growth')return'%';if(mode==='index')return'指数';const u=String(v.unit||'').trim(),c=String(v.currency||'').trim();if(u.includes('%'))return'%';if(c&&u.toUpperCase().startsWith(c.toUpperCase()))return u;return[c,u].filter(Boolean).join(' ')||'数值'};
 const axisUnit=unit(all[0]);
 root.innerHTML=`<div class="chart-head"><div><p class="eyebrow">DATABASE CHART</p><h3>${esc(BY_EN[metric]?.zh)} / ${esc(metric)}</h3><p>${mode==='index'?'基期=100 / Indexed':mode==='growth'?'同比增长 / Growth':'绝对值 / Absolute'} · 单位 / Unit: ${esc(axisUnit)}</p></div></div><div class="chart-wrap"><svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none">${ticks.map(v=>{const yy=y(v);return`<line x1="${p.l}" y1="${yy}" x2="${W-p.r}" y2="${yy}" class="grid-line"/><text x="${p.l-10}" y="${yy+4}" text-anchor="end" class="axis-number">${esc(num(v))}</text>`}).join('')}${periods.map(k=>`<text x="${x(k)}" y="${H-9}" text-anchor="middle" class="axis-label">${esc(k)}</text>`).join('')}${series.map((s,i)=>`<polyline points="${s.values.map(v=>`${x(v.period)},${y(v.value)}`).join(' ')}" fill="none" stroke="${colors[i%colors.length]}" stroke-width="3"/>${s.values.map(v=>`<circle cx="${x(v.period)}" cy="${y(v.value)}" r="4" fill="${colors[i%colors.length]}"></circle><text x="${x(v.period)}" y="${Math.max(14,y(v.value)-10-i*11)}" text-anchor="middle" class="point-label" fill="${colors[i%colors.length]}">${esc(num(v.value))}</text>`).join('')}`).join('')}</svg></div><div class="legend">${series.map((s,i)=>`<span><i style="background:${colors[i%colors.length]}"></i>${esc(s.company?.name)}</span>`).join('')}</div>`
}
